        if (b.dataset.advanced) { this.advanced(b.dataset.advanced);return; }
        if (b.dataset.preset) { this.theme = { ...presets[b.dataset.preset] };this.applyTheme();this.render();return; }
        if (b.dataset.savedTheme) { this.theme = { ...defaults, ...this.bridge.settings.themes[b.dataset.savedTheme] };this.applyTheme();this.render();return; }
