    advanced(section) { if (this.bridge.demo) { this.install();return; } this.closeModal();this.classic = true;delete document.body.dataset.modernView;delete document.body.dataset.modernCollapsed;delete document.body.dataset.modernFocus;this.render();if (section) this.bridge.advanced(section); }
